import{_ as a,C as e,o as i,c as d,a6 as o,E as s,w as c}from"./chunks/framework.DIp0zHSV.js";const m=JSON.parse('{"title":"Connection Overlay","description":"The LCARdS connection overlay: a full-screen screen shown when a browser loses its connection to Home Assistant, as styled text, any card or the Borg assimilation, over effect layers you choose, set for everyone, one user or one device.","frontmatter":{"description":"The LCARdS connection overlay: a full-screen screen shown when a browser loses its connection to Home Assistant, as styled text, any card or the Borg assimilation, over effect layers you choose, set for everyone, one user or one device.","moved_anchors":{"messages":"/configuration/connectivity#screen-overlay","reload-controls":"/configuration/connectivity#broadcast-buttons"}},"headers":[],"relativePath":"configuration/connectivity.md","filePath":"configuration/connectivity.md","lastUpdated":1794184759000}'),l={name:"configuration/connectivity.md"};function h(g,t,p,u,y,f){const n=e("CardDemo"),r=e("ClientOnly");return i(),d("div",null,[t[0]||(t[0]=o('<h1 id="connection-overlay" tabindex="-1">Connection Overlay <a class="header-anchor" href="#connection-overlay" aria-label="Permalink to &quot;Connection Overlay&quot;">​</a></h1><p><strong>The connection overlay covers the screen when a browser loses its connection to Home Assistant, and takes itself away when the connection is back.</strong> On a wall tablet or kiosk you see at once that the dashboard is offline, instead of a screen quietly going stale.</p><ul><li>It is set up in the <strong>Connectivity</strong> tab of <strong>LCARdS Config</strong>, and is off until you turn it on.</li><li>It can show styled text, any card, or the <a href="/dev/core/borg.html">Borg assimilation</a>, over animated effect layers.</li><li>Settings can be the same everywhere, or differ for one user or one device.</li></ul><div class="tip custom-block"><p class="custom-block-title">Try it</p><p><strong>Simulate Disconnect</strong> at the bottom of the tab shows the overlay with your current settings, saved or not, while the dashboard keeps running.</p></div><hr><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p><strong>LCARdS watches each browser&#39;s connection to Home Assistant and shows the overlay when it drops.</strong></p><ul><li>After a drop it waits for the <a href="#general">disconnect tolerance</a> (2.5 seconds by default) before showing the overlay, so short blips during a restart or a network handover pass unseen.</li><li>When the connection is back, and has held for a second, the overlay goes. A short <strong>Connection Restored</strong> message can show first.</li><li>The overlay covers everything on the page, Home Assistant&#39;s own sidebar and header included. It does not wait for the alert mode: during an alert it shows over the alert overlay, and its effect layers take the place of the alert&#39;s.</li></ul><hr><h2 id="setting-up" tabindex="-1">Setting up <a class="header-anchor" href="#setting-up" aria-label="Permalink to &quot;Setting up&quot;">​</a></h2><p><strong>Open LCARdS Config &gt; Connectivity, change the settings, and click Save.</strong></p><ul><li>Nothing is live until you save. A banner says when there are unsaved changes; <strong>Discard changes</strong> goes back to the stored values.</li><li>Pick the <a href="#scope-and-per-device-overrides">scope</a> first (Global, User or Device): <strong>Save</strong> writes to that one.</li></ul><hr><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p><strong>Turns the overlay on, lets people close it, and sets how long a drop must last before it shows.</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Enable connection overlay</strong></td><td>off</td><td>Show the overlay when the connection to Home Assistant is lost</td></tr><tr><td><strong>Allow user to dismiss</strong></td><td>on</td><td>A click on the overlay&#39;s backdrop closes it. It comes back at the next disconnect</td></tr><tr><td><strong>Disconnect tolerance (ms)</strong></td><td><code>2500</code></td><td>How long to wait after a drop before showing the overlay, <code>0</code> to <code>30000</code>. <code>0</code> shows it at once; 2000 to 5000 suits phones and shaky connections</td></tr></tbody></table><hr><h2 id="screen-overlay" tabindex="-1">Screen Overlay <a class="header-anchor" href="#screen-overlay" aria-label="Permalink to &quot;Screen Overlay&quot;">​</a></h2><p><strong>What the overlay shows when the connection is lost, and when it comes back.</strong> The section is collapsed at first.</p><h3 id="display-style" tabindex="-1">Display style <a class="header-anchor" href="#display-style" aria-label="Permalink to &quot;Display style&quot;">​</a></h3><p><strong>Display style picks one of three kinds of overlay.</strong></p><ul><li><strong>Simple text:</strong> styled text over the effect layers. See <a href="#simple-text-mode">Simple text mode</a>.</li><li><strong>Custom card (YAML):</strong> any Home Assistant card, centred or placed where you like. See <a href="#custom-card-mode">Custom card mode</a>.</li><li><strong>Resistance is Futile:</strong> the Borg assimilation runs instead of an overlay. See <a href="#borg-mode">Borg mode</a>.</li></ul><h3 id="simple-text-mode" tabindex="-1">Simple text mode <a class="header-anchor" href="#simple-text-mode" aria-label="Permalink to &quot;Simple text mode&quot;">​</a></h3><p><strong>Styled text, with its own font, size and colour, for the lost and the restored message.</strong></p><h4 id="connection-lost" tabindex="-1">Connection Lost <a class="header-anchor" href="#connection-lost" aria-label="Permalink to &quot;Connection Lost&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Message text</strong></td><td><code>Connection Lost</code></td><td>The text shown while disconnected</td></tr><tr><td><strong>Text colour</strong></td><td><code>var(--error-color)</code></td><td>Any CSS colour, CSS variable or theme token</td></tr><tr><td><strong>Font</strong></td><td><code>Antonio</code></td><td>Pick from the font list, or type a font name</td></tr><tr><td><strong>Size</strong></td><td><code>42</code> px</td><td>Font size, <code>1</code> to <code>200</code> px</td></tr><tr><td><strong>Weight</strong></td><td><code>400</code></td><td>CSS font weight: <code>400</code>, <code>700</code>, <code>bold</code>, <code>lighter</code> ...</td></tr><tr><td><strong>Transform</strong></td><td>UPPERCASE</td><td><strong>UPPERCASE</strong>, <strong>Title Case</strong> or <strong>None</strong></td></tr></tbody></table><h4 id="connection-restored" tabindex="-1">Connection Restored <a class="header-anchor" href="#connection-restored" aria-label="Permalink to &quot;Connection Restored&quot;">​</a></h4><p><strong>A short message when the connection is back, which goes by itself.</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Show reconnect message</strong></td><td>on</td><td>Show the message on reconnect. Off: the overlay just goes</td></tr><tr><td><strong>Message text</strong></td><td><code>Connection Established</code></td><td>The text shown on reconnect</td></tr><tr><td><strong>Text colour</strong></td><td><code>var(--primary-color)</code></td><td>Any CSS colour, CSS variable or theme token</td></tr><tr><td><strong>Font</strong>, <strong>Size</strong>, <strong>Weight</strong>, <strong>Transform</strong></td><td>as for Connection Lost</td><td>Set separately from the lost message</td></tr><tr><td><strong>Auto-dismiss after (seconds)</strong></td><td><code>3</code></td><td>How long the message stays, <code>1</code> to <code>30</code> seconds</td></tr></tbody></table><p>The restored message shows only when the overlay itself was shown: a drop shorter than the tolerance shows neither.</p><h3 id="custom-card-mode" tabindex="-1">Custom card mode <a class="header-anchor" href="#custom-card-mode" aria-label="Permalink to &quot;Custom card mode&quot;">​</a></h3><p><strong>Any Home Assistant card as the disconnect screen: an LCARdS button, a picture, a markdown card, a whole stack.</strong> Paste its YAML into the editor; it shows over the effect layers.</p><ul><li>Grids and stacks may need a width and height: CSS units such as <code>400px</code>, <code>30vw</code> or <code>auto</code>.</li></ul>',33)),s(r,null,{default:c(()=>[s(n,{src:"%23%20A%20card%20to%20paste%20into%20Connection%20Lost%20Card%0Atype%3A%20custom%3Alcards-button%0Apreset%3A%20lozenge%0Atext%3A%0A%20%20name%3A%0A%20%20%20%20content%3A%20NO%20SIGNAL%0A%20%20%20%20show%3A%20true%0Astyle%3A%0A%20%20card%3A%0A%20%20%20%20color%3A%0A%20%20%20%20%20%20background%3A%20var(--lcars-alert-red)%0A"})]),_:1}),t[1]||(t[1]=o(`<div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># A card to paste into Connection Lost Card</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">custom:lcards-button</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">preset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lozenge</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NO SIGNAL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">style</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  card</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      background</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">var(--lcars-alert-red)</span></span></code></pre></div><h4 id="connection-lost-card" tabindex="-1">Connection Lost Card <a class="header-anchor" href="#connection-lost-card" aria-label="Permalink to &quot;Connection Lost Card&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>YAML editor</strong></td><td>empty</td><td>The card&#39;s YAML, as in a dashboard</td></tr><tr><td><strong>Position</strong></td><td>centre</td><td>Where the card sits: one of nine places, from top left to bottom right</td></tr><tr><td><strong>Width</strong></td><td><code>auto</code></td><td>CSS width: <code>400px</code>, <code>40vw</code>, <code>auto</code></td></tr><tr><td><strong>Height</strong></td><td><code>auto</code></td><td>CSS height: <code>300px</code>, <code>30vh</code>, <code>auto</code></td></tr></tbody></table><h4 id="connection-restored-card" tabindex="-1">Connection Restored Card <a class="header-anchor" href="#connection-restored-card" aria-label="Permalink to &quot;Connection Restored Card&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>YAML editor</strong></td><td>empty</td><td>A card shown on reconnect. Empty: the text reconnect message shows instead</td></tr><tr><td><strong>Show reconnect message</strong></td><td>on</td><td>Show the card (or text) on reconnect</td></tr><tr><td><strong>Auto-dismiss after (seconds)</strong></td><td><code>3</code></td><td>How long it stays, <code>1</code> to <code>30</code> seconds</td></tr></tbody></table><h3 id="borg-mode" tabindex="-1">Borg mode <a class="header-anchor" href="#borg-mode" aria-label="Permalink to &quot;Borg mode&quot;">​</a></h3><p><strong>Resistance is Futile: on disconnect the <a href="/dev/core/borg.html">Borg assimilation</a> runs instead of an overlay, and reverses when the connection is back.</strong> The dashboard turns Borg green, its font changes, and the assimilation intro plays over it.</p><ul><li>The assimilation starts once the <a href="#general">disconnect tolerance</a> has passed, as the overlay does, so a short blip shows nothing. A click ends the intro; the Borg colours and effects stay until the connection returns, when the normal deassimilation plays.</li><li>Messages, cards and the Effect Layers section are not used. Instead the mode has its own <strong>Canvas Effect</strong> (always the Borg intro, with its settings), <strong>Backdrop Filter</strong>, <strong>Colour Tint</strong>, <strong>Palette Hue</strong> and <strong>Font Swap</strong>.</li><li><strong>Simulate Disconnect</strong> runs the assimilation with these settings; <strong>Simulate Reconnect</strong> or <strong>Clear Test</strong> reverses it.</li></ul><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Canvas Effect</strong></td><td>the Borg intro: 8 sites, 5 tendrils each, 600 px, 2 particles</td><td>The intro&#39;s settings: renderer, injection sites, tendrils, particles, colours, cube, signal corruption and overrun. See <a href="/dev/core/borg.html#intro-canvas">intro.canvas</a></td></tr><tr><td><strong>Backdrop Filter</strong></td><td><code>saturate</code> <code>200%</code></td><td>A filter on the dashboard during the intro, or <strong>None (disabled)</strong></td></tr><tr><td><strong>Colour Tint</strong></td><td><code>color-tint</code>, a dark green</td><td>A colour over the dashboard during the intro, or <strong>None (disabled)</strong></td></tr><tr><td><strong>Palette hue (degrees)</strong></td><td><code>110</code></td><td>The hue the dashboard colours turn toward, <code>0</code> to <code>359</code>: <code>0</code> red, <code>60</code> yellow, <code>110</code> Borg green, <code>180</code> cyan, <code>240</code> blue, <code>300</code> magenta</td></tr><tr><td><strong>Enable Borg font replacement</strong></td><td>on</td><td>Off: the dashboard keeps its font; everything else still runs</td></tr></tbody></table><hr><h2 id="effect-layers" tabindex="-1">Effect Layers <a class="header-anchor" href="#effect-layers" aria-label="Permalink to &quot;Effect Layers&quot;">​</a></h2><p><strong>Three full-screen effect layers behind the message, each set on its own: an animated canvas, a colour overlay and a backdrop filter.</strong> The section is collapsed at first, and is hidden in Borg mode.</p><table tabindex="0"><thead><tr><th>Layer</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Canvas Effect</strong></td><td>An animation drawn over the page: static, pixelate, glitch, scanlines</td><td><code>static</code> at 0.55 opacity</td></tr><tr><td><strong>Colour Overlay</strong></td><td>A colour over the page</td><td><code>color-tint</code> with <code>rgba(0,0,0,0.55)</code></td></tr><tr><td><strong>Backdrop Filter</strong></td><td>A CSS filter on everything behind it: blur, saturate, grayscale and more</td><td><strong>None (disabled)</strong></td></tr></tbody></table><h3 id="configuring-a-slot" tabindex="-1">Configuring a slot <a class="header-anchor" href="#configuring-a-slot" aria-label="Permalink to &quot;Configuring a slot&quot;">​</a></h3><p><strong>Pick an Effect Preset for a layer; its settings appear under it.</strong> The list holds the built-in <a href="/dev/core/effects/screen-effects.html">screen effects</a> and any a content pack adds. <strong>None (disabled)</strong> turns the layer off.</p><table tabindex="0"><thead><tr><th>Preset</th><th>Layer</th><th>Settings</th></tr></thead><tbody><tr><td><code>static</code></td><td>Canvas</td><td>Opacity, Grain Scale, Tint Color, Tint Strength</td></tr><tr><td><code>pixelate</code></td><td>Canvas</td><td>Pixel Size, Opacity, Light Variance, Base Lightness, Tint Color, Tint Strength</td></tr><tr><td><code>glitch</code></td><td>Canvas</td><td>Intensity, Max Shift, Band Height, Opacity, FPS</td></tr><tr><td><code>scanlines</code></td><td>Canvas</td><td>Line Height, Opacity, Scroll Speed</td></tr><tr><td><code>color-tint</code></td><td>Colour</td><td>Tint Color (any CSS colour; use <code>rgba()</code> for transparency)</td></tr><tr><td><code>vignette</code></td><td>Colour</td><td>Opacity</td></tr><tr><td><code>blur</code></td><td>Backdrop</td><td>Blur Amount (<code>8px</code>)</td></tr><tr><td><code>saturate</code></td><td>Backdrop</td><td>Amount (<code>200%</code>)</td></tr><tr><td><code>grayscale</code></td><td>Backdrop</td><td>Amount (<code>100%</code>)</td></tr><tr><td><code>contrast</code></td><td>Backdrop</td><td>Amount (<code>200%</code>)</td></tr><tr><td><code>hue-rotate</code></td><td>Backdrop</td><td>Angle (<code>180deg</code>)</td></tr></tbody></table><p>Mix them freely: a <code>grayscale</code> backdrop with a <code>color-tint</code> overlay and no canvas gives a washed-out, tinted page with no animation.</p><hr><h2 id="test-controls" tabindex="-1">Test Controls <a class="header-anchor" href="#test-controls" aria-label="Permalink to &quot;Test Controls&quot;">​</a></h2><p><strong>Preview the overlay with your current settings, saved or not.</strong> The dashboard keeps running behind it; nothing is actually disconnected.</p><ul><li><strong>Simulate Disconnect</strong> shows the overlay (and is greyed out while it shows).</li><li><strong>Simulate Reconnect</strong> plays what happens when the connection comes back, the restored message included.</li><li><strong>Clear Test</strong> removes it.</li></ul><div class="tip custom-block"><p class="custom-block-title">Workflow</p><p>Change a setting, click <strong>Simulate Disconnect</strong>, look, adjust, repeat. When it looks right, click <strong>Save</strong>.</p></div><hr><h2 id="scope-and-per-device-overrides" tabindex="-1">Scope and per-device overrides <a class="header-anchor" href="#scope-and-per-device-overrides" aria-label="Permalink to &quot;Scope and per-device overrides&quot;">​</a></h2><p><strong>Settings can be the same for everyone, or differ for one user or one browser.</strong> A browser uses its device&#39;s setting first, then its user&#39;s, then the global one, then the built-in default.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Device  →  User  →  Global</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Scope</th><th>Who it applies to</th></tr></thead><tbody><tr><td><strong>Global</strong></td><td>Every user and device</td></tr><tr><td><strong>User</strong></td><td>Your Home Assistant user, on any device</td></tr><tr><td><strong>Device</strong></td><td>This browser, whoever is logged in</td></tr></tbody></table><ul><li>Pick the scope with the switch at the top of the tab. Each setting shows a badge for where its value comes from; the clear button next to it removes the override at this scope.</li><li><strong>Save (scope)</strong> writes only the settings you changed, so the others keep coming from the scopes below.</li><li><strong>Reset (scope)</strong> removes every override stored at that scope, after a confirmation.</li></ul><h3 id="admin-editing-another-device-or-user" tabindex="-1">Admin: editing another device or user <a class="header-anchor" href="#admin-editing-another-device-or-user" aria-label="Permalink to &quot;Admin: editing another device or user&quot;">​</a></h3><p><strong>Administrators can pick another user or device in the scope switch and save settings for it.</strong> The browser it belongs to picks them up within seconds, with no reload.</p><ul><li>If you have the tab open on a device whose settings another administrator changes, and you have no unsaved edits, the tab refreshes itself.</li><li>With unsaved edits, a banner says <strong>Settings were updated from another device</strong> with <strong>Discard edits &amp; refresh</strong>; your edits stay until you choose.</li></ul><h3 id="broadcast-buttons" tabindex="-1">Broadcast buttons <a class="header-anchor" href="#broadcast-buttons" aria-label="Permalink to &quot;Broadcast buttons&quot;">​</a></h3><p><strong>Two administrator buttons at the bottom act on every connected browser.</strong></p><table tabindex="0"><thead><tr><th>Button</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Push Live Config</strong></td><td>Every connected browser reads its overlay settings again, with no page reload. Use it for a device that was offline when you saved</td></tr><tr><td><strong>Reload All Clients</strong></td><td>Every connected browser reloads its page. A last resort</td></tr></tbody></table><hr><h2 id="upgrading-existing-stored-settings" tabindex="-1">Upgrading: existing stored settings <a class="header-anchor" href="#upgrading-existing-stored-settings" aria-label="Permalink to &quot;Upgrading: existing stored settings&quot;">​</a></h2><p><strong>Settings saved before field-by-field saving existed may hold every field at one scope.</strong> That is harmless: the values are right and the scopes still apply in order.</p><p>To keep only the overrides you meant at device scope:</p><ol><li>Open <strong>Connectivity</strong>, pick the <strong>Device</strong> scope for that device and note which settings should differ from the user or global ones.</li><li>Click <strong>Reset device</strong> to remove all its device overrides.</li><li>Change and save only the settings you want to pin to the device.</li></ol><p>Afterwards only those settings show a <strong>device</strong> badge.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./">Configuration overview</a>: all Config Panel tabs</li><li><a href="./users-devices.html">Users &amp; Devices</a>: manage stored per-device and per-user settings</li><li><a href="/dev/core/effects/screen-effects.html">Screen Effects</a>: the effect presets and their settings</li><li><a href="/dev/core/borg.html">Borg Assimilation</a>: what the Borg mode plays</li><li><a href="./../architecture/subsystems/connection-overlay.html">Connection Overlay Service</a>: developer reference</li></ul>`,43))])}const v=a(l,[["render",h]]);export{m as __pageData,v as default};
